import Foundation

enum WebPage {
    static let html = #"""
    <!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light dark"><title>局域网传输</title>
    <style>
    :root{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color-scheme:light dark}*{box-sizing:border-box}body{margin:0;background:Canvas;color:CanvasText}main{max-width:660px;margin:auto;padding:24px 18px 60px}h1{font-size:29px;margin:16px 0 4px}h2{font-size:19px;margin:0 0 16px}.hint{color:gray;font-size:14px;line-height:1.5}.card{border:1px solid color-mix(in srgb,CanvasText 16%,transparent);border-radius:18px;padding:20px;margin-top:22px}button,.button{appearance:none;border:0;border-radius:11px;background:#0866d8;color:white;font:600 16px -apple-system,sans-serif;padding:13px 18px;min-height:48px;cursor:pointer;display:inline-flex;align-items:center;justify-content:center}button.secondary{background:color-mix(in srgb,CanvasText 12%,Canvas);color:CanvasText}button:disabled{opacity:.5}input[type=file]{display:none}.row{display:flex;gap:10px;align-items:center;justify-content:space-between}.file{padding:13px 0;border-top:1px solid color-mix(in srgb,CanvasText 13%,transparent);min-width:0}.filename{overflow-wrap:anywhere;font-weight:550}.small{font-size:13px;color:gray;margin-top:3px}progress{width:100%;height:13px;margin:12px 0}.notice{min-height:22px;margin-top:12px;font-size:14px}.error{color:#d23636}.good{color:#228044}a.download{text-decoration:none;white-space:nowrap;font-weight:600;color:#0866d8;padding:10px}#empty{color:gray}
    </style></head><body><main><h1>局域网传输</h1><p class="hint">设备已连接到 Mac。保持两个设备在同一个 Wi-Fi 或手机热点中。</p>
    <section class="card"><h2>传到 Mac</h2><label class="button" for="picker">选择文件</label><input id="picker" type="file" multiple><div id="uploadName" class="small"></div><progress id="progress" max="100" value="0" hidden></progress><div class="row"><span id="uploadState" class="notice" role="status"></span><button id="cancel" class="secondary" hidden>取消</button></div></section>
    <section class="card"><div class="row"><h2>从 Mac 下载</h2><button id="refresh" class="secondary">刷新</button></div><div id="files"><p id="empty">正在读取文件…</p></div></section>
    <p class="hint">上传到 Mac 的接收目录；此处显示 Mac 共享目录中的文件。单文件上限 2 GB。传输中请保持页面打开。</p></main>
    <script>
    const picker=document.getElementById('picker'), progress=document.getElementById('progress'), state=document.getElementById('uploadState'), cancel=document.getElementById('cancel'), maxFileBytes=2*1073741824;let current=null, stopped=false;
    function size(n){if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';if(n<1073741824)return(n/1048576).toFixed(1)+' MB';return(n/1073741824).toFixed(2)+' GB'}
    function message(text,error=false){state.textContent=text;state.className='notice '+(error?'error':'good')}
    function upload(file){return new Promise(resolve=>{if(file.size>maxFileBytes){message(file.name+' 超过 2 GB，无法上传',true);resolve(false);return}const xhr=new XMLHttpRequest();current=xhr;progress.hidden=false;progress.value=0;cancel.hidden=false;document.getElementById('uploadName').textContent=file.name+' · '+size(file.size);message('正在上传…');xhr.open('PUT','/api/upload?name='+encodeURIComponent(file.name));xhr.upload.onprogress=e=>{if(e.lengthComputable){progress.value=e.loaded/e.total*100;message('正在上传… '+Math.round(progress.value)+'%')}};xhr.onload=()=>{current=null;cancel.hidden=true;if(xhr.status===201){let result=JSON.parse(xhr.responseText);message('已保存：'+result.name);resolve(true)}else{message(xhr.responseText||'上传失败，请重试',true);resolve(false)}};xhr.onerror=()=>{current=null;cancel.hidden=true;message('网络中断，请检查 Wi-Fi 后重新上传',true);resolve(false)};xhr.onabort=()=>{current=null;cancel.hidden=true;message('已取消上传',true);resolve(false)};xhr.send(file)})}
    picker.onchange=async()=>{stopped=false;picker.disabled=true;for(const file of picker.files){if(stopped)break;const ok=await upload(file);if(!ok)break}picker.disabled=false;picker.value=''};
    cancel.onclick=()=>{stopped=true;current?.abort()};
    async function refresh(){const box=document.getElementById('files');try{const response=await fetch('/api/files',{cache:'no-store'});if(response.status===401){box.textContent='会话已过期，请重新扫描 Mac 上的二维码。';return}if(!response.ok)throw Error('读取失败');const files=await response.json();box.replaceChildren();if(!files.length){const p=document.createElement('p');p.id='empty';p.textContent='共享目录暂无文件';box.append(p)}for(const file of files){const row=document.createElement('div');row.className='row file';const info=document.createElement('div');info.style.minWidth='0';const name=document.createElement('div');name.className='filename';name.textContent=file.name;const meta=document.createElement('div');meta.className='small';meta.textContent=size(file.size);info.append(name,meta);const link=document.createElement('a');link.className='download';link.textContent='下载';link.href='/api/file?name='+encodeURIComponent(file.name);row.append(info,link);box.append(row)}}catch(e){box.textContent='无法读取文件列表，请检查连接并重试。'}}
    document.getElementById('refresh').onclick=refresh;refresh();
    </script></body></html>
    """#
}
